const layer = new Uint8Array(V2_HEADER_LENGTH + ciphertext.length);
layer.set(V2_MAGIC, 0);
layer[V2_MAGIC.length] = V2_ALG_AES_GCM;
new DataView(layer.buffer).setUint32(V2_MAGIC.length + 1, iterations, false);
layer.set(salt, V2_PREFIX_LENGTH);
layer.set(iv, V2_PREFIX_LENGTH + SALT_LENGTH);
layer.set(ciphertext, V2_HEADER_LENGTH);

private static parseV2Iterations(layer: Uint8Array): number | null {
  if (layer.length < V2_MIN_LENGTH) return null;
  for (let i = 0; i < V2_MAGIC.length; i++) {
    if (layer[i] !== V2_MAGIC[i]) return null;
  }
  if (layer[V2_MAGIC.length] !== V2_ALG_AES_GCM) return null;
  const iterations = new DataView(layer.buffer, layer.byteOffset, layer.byteLength)
    .getUint32(V2_MAGIC.length + 1, false);
  if (iterations < 1 || iterations > MAX_ITERATIONS) return null;
  return iterations;
}

// Una sal y una derivación PBKDF2 por contraseña para todo el archivo;
// cada trozo reutiliza la clave con un IV aleatorio nuevo.
const passwordKeys: { key: CryptoKey; salt: Uint8Array }[] = [];
for (const password of validPasswords) {
  const salt = window.crypto.getRandomValues(new Uint8Array(SALT_LENGTH));
  const key = await this.deriveKey(password, salt, iterations, 'AES-GCM');
  passwordKeys.push({ key, salt });
}

while (offset < fileSize) {
  const chunk = file.slice(offset, offset + CHUNK_SIZE);
  const chunkBuffer = await chunk.arrayBuffer();
  let currentData: Uint8Array<ArrayBuffer> = new Uint8Array(chunkBuffer);
  for (const { key, salt } of passwordKeys) {
    currentData = await this.encryptLayerWithKey(currentData, key, salt, iterations);
  }
  // ...capa RSA opcional, tamaño del trozo y escritura
  offset += CHUNK_SIZE;
}

/// Un solo uso: queda consumido en CUALQUIER llamada; true solo si no
/// se había usado, es más joven que el TTL y coincide (en tiempo constante).
pub fn try_consume(&mut self, candidate: &str, now: Instant) -> bool {
    let was_consumed = std::mem::replace(&mut self.consumed, true);
    let fresh = now.saturating_duration_since(self.created) <= PAIRING_TTL;
    let equal = crate::server::constant_time_eq(candidate, &self.code);
    !was_consumed && fresh && equal
}

const PAIR_RE = /^#shred&pair=([1-9]\d{3,4})\.([A-Za-z0-9_-]{22})$/

export function capturePairingFromHash(hash: string): boolean {
  // Un intento fallido no puede dejar vivo un código anterior.
  pending = null
  const m = PAIR_RE.exec(hash)
  if (!m) return false
  const port = Number(m[1])
  if (port < 1024 || port > 65535) return false
  pending = { port, code: m[2]! }
  return true
}

/// La raíz abierta tiene que ser exactamente el objeto que se registró al elegir.
fn require_identity(handle: &File, expected: &FileIdentity) -> Result<(), Refusal> {
    if identity_of_handle(handle)? == *expected {
        Ok(())
    } else {
        Err(Refusal::RootChanged)
    }
}

